		<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>                                        <td>{pigcms{$vo.log_id}</td>                                        <td style="max-width: 200px;word-wrap: break-word;">{pigcms{$vo.code_info}</td>                                        <td>                                            <if condition="$vo['type'] eq 1">                                                用户ID：{pigcms{$vo.uid} | <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('User/edit',array('uid'=>$vo['uid'],'frame_show'=>true))}','查看用户信息',750,650,true,false,false,false,'user_detail',true);">查看用户信息</a>                                                <elseif condition="$vo['type'] eq 0"/>                                                管理员ID：{pigcms{$vo.uid}                                                <elseif condition="$vo['type'] eq 2"/>                                                商户ID：{pigcms{$vo.uid}                                            </if>                                        </td>										<td>{pigcms{$log_type[$vo['log_type']]}</td>                                        <td style="display: none;"><pre style="width:100%;overflow-x:auto;">{pigcms{$vo.log_post|unserialize=###|print_r=###}</pre></td>                                        <td>{pigcms{$vo.log_time|date="Y-m-d H:i:s",###}</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="6">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="6">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><include file="Public:footer"/>